d_m(a){return A.c(a)+" \u043f\u043e \u0441\u0442\u0440\u0430\u043d\u0435 \xb7 \u0441\u043c\u0435\u043d\u0438\u0442\u044c"},
d_w(a){return"\u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c \u0441\u043a\u0430\u0437\u0430\u0442\u044c: "+A.c(a)},
d_E(a){return"\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0439 \u0432 \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u0435: "+A.c(a)},
d_M(a){return"\u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c: "+A.c(a)},
d_U(a){return"\u0413\u043e\u0432\u043e\u0440\u044e \u043d\u0430: "+A.c(a)},
